#define FILE_TO_CHECK "data/config.txt"

// Check for existence and read permission
int check_mode = F_OK | R_OK;

// Use AT_FDCWD for CWD relative path,
// AT_SYMLINK_NOFOLLOW to avoid resolving links.
int operation_flags = AT_SYMLINK_NOFOLLOW;

int check_result = faccessat2(
    AT_FDCWD,
    FILE_TO_CHECK,
    check_mode,
    operation_flags
);

// Optional: Use AT_EACCESS flag to check effective UID/GID
// rather than real UID/GID.

if (check_result != 0) {
    /* Access denied or file does not exist (errno) */
}
